#!/data/data/com.termux/files/usr/bin/bash
set -e
cd ~/bstm-marketplace-app
base64 -d > js/bstm-core.js << 'BSTMCORE'

BSTMCORE
base64 -d > js/pages/seller-dashboard.js << 'SELLERJS'

SELLERJS
base64 -d > js/pages/analytics.js << 'ANALYTICSJS'

ANALYTICSJS
base64 -d > js/pages/earnings.js << 'EARNINGSJS'

EARNINGSJS
base64 -d > js/pages/room.js << 'ROOMJS'

ROOMJS
base64 -d > room.html << 'ROOMHTML'

ROOMHTML
base64 -d > seller-dashboard.html << 'SELLERHTML'

SELLERHTML
base64 -d > analytics.html << 'ANALYTICSHTML'

ANALYTICSHTML
base64 -d > earnings.html << 'EARNINGSHTML'

EARNINGSHTML
for f in js/bstm-core.js js/pages/seller-dashboard.js js/pages/analytics.js js/pages/earnings.js js/pages/room.js; do
  node --check "$f" || { echo "SYNTAX FAIL: $f"; exit 1; }
done
echo "All syntax checks passed."
for f in js/bstm-core.js js/pages/seller-dashboard.js js/pages/analytics.js js/pages/earnings.js js/pages/room.js room.html seller-dashboard.html analytics.html earnings.html; do
  sz=$(wc -c < "$f")
  echo "$f: $sz bytes"
done
git add js/bstm-core.js js/pages/seller-dashboard.js js/pages/analytics.js js/pages/earnings.js js/pages/room.js room.html seller-dashboard.html analytics.html earnings.html
git commit -m "Real seller/staff access gate on seller-dashboard, analytics, earnings; room business info (contact/hours/address/policies) + real reviews summary on room.html"
git push
